CREATE OR REPLACE VIEW pg_compat.pg_columns AS SELECT table_catalog::VARCHAR, CASE WHEN table_schema = 'main' THEN 'public' ELSE table_schema END AS table_schema, table_name::VARCHAR, column_name::VARCHAR, ordinal_position::INTEGER, column_default::VARCHAR, is_nullable::VARCHAR, data_type::VARCHAR, data_type AS udt_name FROM information_schema.columns WHERE table_schema IN ('public', 'main')